"""Torch fallback for FP8 row-wise quantization."""


import torch


_FP8_E4M3_MAX = 448.0


def fp8_quant_torch_into(
    *,
    out_bits: torch.Tensor,
    out_scale: torch.Tensor,
    inp: torch.Tensor,
) -> None:
    absmax = inp.abs().amax(dim=1).float()
    scale = (absmax / _FP8_E4M3_MAX).clamp(min=1e-6)
    out_scale.copy_(scale)
    x_scaled = inp.float() / scale.unsqueeze(1)
    x_clamped = x_scaled.clamp(-_FP8_E4M3_MAX, _FP8_E4M3_MAX)
    out_bits.copy_(x_clamped.to(torch.float8_e4m3fn).view(torch.uint8))


def fp8_block_quant_torch_into(
    *,
    out: torch.Tensor,
    out_scale: torch.Tensor,
    inp: torch.Tensor,
    block_k: int = 128,
) -> None:
    if inp.ndim != 2:
        raise ValueError(f"block FP8 quant expects 2D input, got {inp.ndim}D")
    if int(inp.shape[1]) % block_k != 0:
        raise ValueError(f"input K={int(inp.shape[1])} must be divisible by block_k={block_k}")
    if out.shape != inp.shape:
        raise ValueError(f"out shape {tuple(out.shape)} must match input {tuple(inp.shape)}")
    expected_scale_shape = (int(inp.shape[0]), int(inp.shape[1]) // block_k)
    if tuple(out_scale.shape) != expected_scale_shape:
        raise ValueError(
            f"out_scale shape {tuple(out_scale.shape)} must be {expected_scale_shape}"
        )

    blocks = inp.float().reshape(inp.shape[0], inp.shape[1] // block_k, block_k)
    scale = (blocks.abs().amax(dim=2) / _FP8_E4M3_MAX).clamp(min=1e-6)
    out_scale.copy_(scale)
    quant = (blocks / scale.unsqueeze(-1)).clamp(-_FP8_E4M3_MAX, _FP8_E4M3_MAX)
    quant = quant.reshape_as(inp).to(torch.float8_e4m3fn)
    if out.dtype == torch.uint8:
        out.copy_(quant.view(torch.uint8))
    else:
        out.copy_(quant)


__all__ = ["fp8_quant_torch_into", "fp8_block_quant_torch_into"]
